CSS = r'''
:root{--paper:#F3F5F2;--surface:#fff;--ink:#17231C;--muted:#56645B;--rule:#D3DAD4;--board:#1F4A37;--slot:#163828;--away:#2E5C9A;--home:#B42A30;--actual:#F0B23A;--display:"Barlow Condensed","Arial Narrow",sans-serif;--body:"Atkinson Hyperlegible",system-ui,sans-serif}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.5 var(--body)}button,a{touch-action:manipulation}button{font:inherit;min-height:44px;cursor:pointer;border:1px solid var(--rule);background:var(--surface);color:var(--ink);padding:10px 14px;border-radius:4px}a{color:var(--board)}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--away);outline-offset:2px}button[aria-selected=true],button.selected{background:var(--board);border-color:var(--board);color:white}button:hover{border-color:var(--board)}[hidden]{display:none!important}h1,h2,h3,h4,.num{font-family:var(--display);font-variant-numeric:tabular-nums}h1{font-size:34px;line-height:1.1;margin:6px 0 12px}h2{font-size:28px;line-height:1.15;margin:28px 0 16px}h3{font-size:24px;line-height:1.15;margin:12px 0}p{margin:8px 0 16px}.subtle{color:var(--muted)}.topbar{background:white;border-bottom:1px solid var(--rule)}.topbar-inner{max-width:1160px;margin:auto;padding:16px 20px}.brand{font:700 24px/1 var(--display);color:var(--board);text-decoration:none;display:inline-flex;align-items:center;min-height:44px}main{max-width:1160px;margin:auto;padding:16px 20px 64px}.nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:24px}.nav button{flex:1 1 auto}.status-note{margin:10px 0 20px;color:var(--muted)}.slate-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr));gap:18px}.game-card{text-align:left;width:100%;border:1px solid var(--rule);border-radius:6px;padding:0;background:white;overflow:hidden;display:block;text-decoration:none;color:var(--ink);min-height:44px}.card-top{padding:14px 16px;border-bottom:1px solid var(--rule);display:flex;justify-content:space-between;gap:8px}.card-team{display:grid;grid-template-columns:1fr 62px;gap:10px;padding:14px 16px 0;align-items:center}.card-team strong{display:block;font:600 24px/1.15 var(--display)}.card-team .num{text-align:right;font-size:34px;font-weight:600}.away{color:var(--away)}.home{color:var(--home)}.starter{color:var(--muted);font-size:16px;line-height:1.3;margin-top:5px}.card-foot{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid var(--rule);margin-top:16px;padding:14px 16px}.card-foot .num{font-size:26px}.actual-chip{background:var(--actual);color:var(--ink);padding:2px 7px;border-radius:2px;display:inline-block}.board{color:#F5F3EA;background:var(--board);border-radius:6px;padding:18px 16px;margin:10px 0 20px}.board-meta{display:flex;justify-content:space-between;gap:10px;color:#D7E2DA}.board-team{display:grid;grid-template-columns:1fr 72px 65px;gap:8px;align-items:center;padding-top:16px}.board-team .name{font:600 27px/1.1 var(--display)}.board-team .starter{color:#D7E2DA}.board-team .num{font-size:36px;text-align:right;line-height:1}.board-labels{display:grid;grid-template-columns:1fr 72px 65px;gap:8px;margin-top:16px;color:#D7E2DA;text-align:right;font-size:16px}.board-actual{border-top:1px solid #49715E;margin-top:16px;padding-top:12px;display:flex;justify-content:space-between;align-items:center}.board-actual .num{color:var(--actual);font-size:32px}.team-section{background:white;border:1px solid var(--rule);border-radius:6px;margin:14px 0;overflow:hidden}.section-label{padding:14px 16px;border-bottom:1px solid var(--rule);font-family:var(--display);font-weight:600;font-size:24px}.box-players{padding:0 16px}.player-row{border-bottom:1px solid var(--rule);padding:16px 0}.player-row:last-child{border:0}.player-head{display:flex;gap:10px;align-items:baseline;margin-bottom:10px}.spot{display:inline-block;color:var(--muted);min-width:18px}.player-name{font-size:18px;font-weight:700;line-height:1.3}.player-position{color:var(--muted)}.stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px 4px}.stat{min-width:0}.stat-label{font-size:16px;display:block;color:var(--muted)}.stat .num{font-size:23px;line-height:1.1}.stat .actual-chip{font-size:21px;margin-left:4px}.comparison-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 12px}.comparison-grid .stat{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--rule);padding:6px 0}.comparison-grid .stat-label{color:var(--muted)}.line-panel{background:white;border:1px solid var(--rule);border-radius:6px;padding:14px 12px}.innings-group{width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:12px}.innings-group th,.innings-group td{text-align:center;padding:7px 0;font-weight:400;font-size:16px}.innings-group td{font:500 22px/1.2 var(--display)}.innings-group th:first-child,.innings-group td:first-child{width:48px;text-align:left}.innings-group thead{border-bottom:1px solid var(--rule)}.actual-line td,.actual-line .num{background:var(--actual);color:var(--ink)}.totals{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid var(--rule);padding-top:12px}.totals>div{display:flex;align-items:center;gap:12px}.totals .num{font-size:25px}.sample-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.sample-buttons button:first-child{grid-column:1/-1}.sample-buttons button{text-align:left;padding:14px}.sample-buttons .num{font-size:24px;display:block}.sample-back{margin-bottom:10px}.play-half{background:white;border:1px solid var(--rule);border-radius:5px;margin:10px 0}.play-half summary{cursor:pointer;min-height:48px;padding:12px 14px;font-weight:700}.play{border-top:1px solid var(--rule);padding:12px 14px}.play p{margin:4px 0}.play-result{display:flex;justify-content:space-between;gap:8px;color:var(--muted)}.play-result .num{font-size:22px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:16px 0}.metric{background:white;border:1px solid var(--rule);padding:12px 8px;border-radius:5px;min-width:0}.metric .num{display:block;font-size:31px}.metric span:first-child{font-size:16px;color:var(--muted);line-height:1.2;display:block;min-height:38px}.track-game{background:white;border:1px solid var(--rule);border-radius:5px;padding:14px;margin:12px 0}.track-game button{display:block;width:100%;text-align:left;margin:12px 0 0}.scoretable{width:100%;border-collapse:collapse;table-layout:fixed;font-size:16px}.scoretable th,.scoretable td{padding:10px 5px;text-align:left;border-bottom:1px solid var(--rule)}.scoretable td.num{font-size:23px}.notes{max-width:760px}.notes p{margin-bottom:22px}.jump-links{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.jump-links a{display:inline-flex;align-items:center;min-height:44px;border:1px solid var(--rule);padding:8px 12px;background:white;border-radius:4px;text-decoration:none}.history-list{background:white;border:1px solid var(--rule);border-radius:5px;margin:20px 0}.history-list summary{min-height:44px;padding:12px;cursor:pointer}.history-version{padding:12px;border-top:1px solid var(--rule)}.legend{display:flex;gap:15px;align-items:center}.placeholder{padding:20px;border:1px solid var(--rule);background:white}.footer{border-top:1px solid var(--rule);margin-top:36px;padding-top:16px;color:var(--muted)}.chart{width:100%;height:auto;display:block;background:white;border:1px solid var(--rule)}@media(min-width:760px){.team-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.team-pair .team-section{margin-top:0}.board{max-width:780px;padding:24px}.board-team .name{font-size:34px}.board-team .num{font-size:44px}.line-panel{max-width:780px}.sample-buttons{grid-template-columns:repeat(5,1fr)}.sample-buttons button:first-child{grid-column:auto}.stat-grid{grid-template-columns:repeat(6,minmax(0,1fr))}}@media(max-width:440px){main{padding:14px 16px 48px}.topbar-inner{padding:8px 16px}.nav{gap:6px}.nav button{padding:10px 9px}.board-team{grid-template-columns:1fr 61px 52px}.board-labels{grid-template-columns:1fr 61px 52px}.board-team .name{font-size:25px}.board-team .num{font-size:32px}}
'''

JS = r'''
'use strict';
const D=window.BRL, $=s=>document.getElementById(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n1=v=>v==null?'—':Number(v).toFixed(1), n3=v=>v==null?'Not yet':Number(v).toFixed(3), pct=v=>v==null?'—':Math.round(v*100)+'%';
const ET=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit',timeZoneName:'short'}), DAY=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',month:'long',day:'numeric',year:'numeric'});
const eastern=t=>t?ET.format(new Date(t)):'Time pending';
let current=null,sample=null;
function versions(pk){return Object.entries(D.forecasts).filter(([id,f])=>String(f.game_pk)===String(pk)).sort((a,b)=>a[1].saved_at.localeCompare(b[1].saved_at));}
function boxFor(pk){return Object.entries(D.box_scores||{}).filter(([id,b])=>String(b.game_pk)===String(pk)).sort((a,b)=>a[1].saved_at.localeCompare(b[1].saved_at)).at(-1);}
function latest(pk){return versions(pk).at(-1);}
function tab(view){for(const v of ['slate','game','sample','track','how'])$(v).hidden=v!==view;for(const v of ['slate','track','how'])$(v+'Tab').setAttribute('aria-selected',String(view===v));window.scrollTo(0,0);}
function teamName(f,s){return esc(f[s].name)}
function starter(b,s){return b?.starters?.[s]?.name||'Starter not saved';}
function metrics(){const s=D.scores||{};return `<div class="metrics"><div class="metric"><span>Model Brier</span><b class="num">${n3(s.model_brier)}</b></div><div class="metric"><span>Team baseline</span><b class="num">${n3(s.team_brier)}</b></div><div class="metric"><span>Market</span><b class="num">${n3(s.market_brier)}</b></div></div>`;}
function renderSlate(){const ids=[...new Set(Object.values(D.forecasts).filter(f=>f.date===D.date).map(f=>String(f.game_pk)))];
 $('slate').innerHTML=`<h1>${D.view_scope==='historical_replay'?'Game replay':"Today's games"}</h1><p class="status-note">${document.body.dataset.refreshBlocked?'Showing last saved forecasts.':esc(D.date)+'. All times Eastern.'}</p><div class="slate-grid">${ids.map(pk=>{const [id,f]=latest(pk),b=boxFor(pk)?.[1],a=D.actuals[pk];return `<button class="game-card" data-game="${pk}" aria-label="Open ${teamName(f,'away')} at ${teamName(f,'home')} box score"><div class="card-top"><span>${eastern(f.scheduled_start)}</span><span>${a?'Final':'Pregame'}</span></div>${['away','home'].map(s=>`<div class="card-team"><div><strong class="${s}">${teamName(f,s)}</strong><div class="starter">${esc(starter(b,s))}</div></div><b class="num ${s}">${pct(s==='home'?f.home_win_probability:1-f.home_win_probability)}</b></div>`).join('')}<div class="card-foot"><div>Projected score<br><b class="num">${n1(f.projected_away_runs)} – ${n1(f.projected_home_runs)}</b></div><div>Actual score<br>${a?`<b class="num actual-chip">${a.away} – ${a.home}</b>`:'—'}</div></div></button>`}).join('')||'<p>No games have a saved forecast yet.</p>'}</div>`;
 $('slate').querySelectorAll('[data-game]').forEach(el=>el.onclick=()=>openGame(el.dataset.game));}
function header(f,b,a){return `<div class="board"><div class="board-meta"><span>${eastern(f.scheduled_start)}</span><span>${a?'Final':'10,000 games'}</span></div><div class="board-labels"><span></span><span>Win</span><span>Runs</span></div>${['away','home'].map(s=>`<div class="board-team"><div><div class="name">${teamName(f,s)}</div><div class="starter">${esc(starter(b,s))}</div></div><b class="num">${pct(s==='home'?f.home_win_probability:1-f.home_win_probability)}</b><b class="num">${n1(f['projected_'+s+'_runs'])}</b></div>`).join('')}${a?`<div class="board-actual"><span>Actual score</span><b class="num">${a.away} – ${a.home}</b></div>`:''}</div>`;}
function lineScore(f,innings,batting,projected=true){const format=projected?n1:v=>v==null?'—':String(v), extras={};for(const s of ['away','home'])extras[s]=Object.entries(innings[s]||{}).filter(([i])=>Number(i)>9).reduce((a,[i,v])=>a+v.R,0);
 const last=Math.max(9,...Object.keys(innings.away||{}).map(Number),...Object.keys(innings.home||{}).map(Number)); const groups=[];for(let start=1;start<=last;start+=5)groups.push(Array.from({length:Math.min(5,last-start+1)},(_,j)=>start+j));return `<div class="line-panel">${groups.map(group=>`<table class="innings-group"><thead><tr><th>Team</th>${group.map(i=>`<th>${i}</th>`).join('')}</tr></thead><tbody>${['away','home'].map(s=>`<tr><th class="${s}">${esc(f[s].abbr)}</th>${group.map(i=>`<td>${format(i==='Extra'?extras[s]:innings[s]?.[i]?.R??(projected?0:null))}</td>`).join('')}</tr>`).join('')}</tbody></table>`).join('')}<div class="totals">${['away','home'].map(s=>{const rows=batting[s];const r=rows.reduce((a,b)=>a+(b.means?b.means.R:b.R),0),h=rows.reduce((a,b)=>a+(b.means?b.means.H:b.H),0);return `<div><span class="${s}">${esc(f[s].abbr)}</span><span>R <b class="num">${format(r)}</b></span><span>H <b class="num">${format(h)}</b></span></div>`}).join('')}</div></div>`;}
const batMetrics=['PA','AB','H','2B','HR','R','RBI','BB','K','HBP','Hit chance','HR chance'];
const pitchMetrics=['Pitch chance','IP','PC','H','R','BB','K','HR'];
function ip(outs){return Math.floor(outs/3)+'.'+(outs%3);}
function statValue(row,k,kind,projected){if(k==='Hit chance')return pct(row.hit_probability);if(k==='HR chance')return pct(row.hr_probability);if(k==='Pitch chance')return pct(row.appearance_probability);if(k==='IP')return projected?n1(row.means.outs/3):ip(row.outs);return projected?n1(row.means[k]):row[k]??'—';}
function players(f,box,kind,projected,actual){const metrics=kind==='batting'?batMetrics:pitchMetrics;
 return `<div class="team-pair">${['away','home'].map(s=>{let rows=projected?box.teams[s][kind]:box[kind][s];if(projected&&kind==='pitching')rows=rows.filter(r=>r.appearance_probability>0);
 const ai=Object.fromEntries((actual?.[kind]?.[s]||[]).map(r=>[r.player_id,r]));const seen=new Set(rows.map(r=>r.player_id));let visible=metrics.filter(k=>projected||!k.includes('chance'));
 return `<section class="team-section"><div class="section-label ${s}">${teamName(f,s)}</div><div class="box-players">${rows.map(row=>{const a=ai[row.player_id],compare=!!actual;return `<div class="player-row"><div class="player-head">${kind==='batting'?`<span class="spot num">${row.spot||'—'}</span>`:''}<span class="player-name">${esc(row.name)}</span></div><div class="${compare?'comparison-grid':'stat-grid'}">${visible.map(k=>{let av='—';if(a)av=k==='IP'?ip(a.outs):a[k]??'—';else if(compare&&!k.includes('chance'))av=k==='IP'?'0.0':'0';return `<div class="stat"><span class="stat-label">${k==='PC'?'Pitches*':k}</span><span><b class="num">${statValue(row,k,kind,projected)}</b>${compare&&!k.includes('chance')?` <b class="num actual-chip">${av}</b>`:''}</span></div>`}).join('')}</div></div>`}).join('')}${(actual?.[kind]?.[s]||[]).filter(r=>!seen.has(r.player_id)).map(row=>`<div class="player-row"><div class="player-head"><span class="player-name">${esc(row.name)}</span></div><p>No pregame player projection</p><div class="stat-grid">${visible.filter(k=>!k.includes('chance')).map(k=>`<div class="stat"><span class="stat-label">${k}</span><b class="num actual-chip">${k==='IP'?ip(row.outs):row[k]??'—'}</b></div>`).join('')}</div></div>`).join('')}</div></section>`}).join('')}</div>`;
}
function openGame(pk){current=String(pk);sample=null;const pair=latest(pk);if(!pair)return;const [id,f]=pair,boxPair=boxFor(pk),b=boxPair?.[1],a=D.actuals[pk],actual=D.actual_boxes?.[pk];
 const versionsHTML=versions(pk).map(([i,v])=>`<div class="history-version">Version ${v.version}. Saved ${eastern(v.saved_at)}.<br>${pct(v.home_win_probability)} ${esc(v.home.abbr)}. Projected ${n1(v.projected_away_runs)} – ${n1(v.projected_home_runs)}.</div>`).join('');
 $('game').innerHTML=`<button class="sample-back" id="backSlate">Back to games</button><h1>Game box score</h1>${header(f,b,a)}<p class="status-note">${Object.values(f.lineup_status).every(x=>x==='official')?'Official lineups':'Projected lineup'}. ${D.view_scope==='historical_replay'?'Replay made':'Saved'} ${eastern(b?.saved_at||f.saved_at)}.</p>${b?`<div class="jump-links"><a href="#projectedBatting">Batting</a><a href="#projectedPitching">Pitching</a><a href="#simulatedGames">Simulated games</a></div><h2>Projected line score</h2>${lineScore(f,b.line_score,{away:b.teams.away.batting,home:b.teams.home.batting})}${actual?`<h2>Actual line score</h2><div class="actual-line">${lineScore(f,actual.innings,actual.batting,false)}</div><p class="legend"><span>Projection</span><span class="actual-chip">Actual</span></p>`:''}<h2 id="projectedBatting">${actual?'Batting: projected and actual':'Projected batting'}</h2>${players(f,b,'batting',true,actual)}<h2 id="projectedPitching">${actual?'Pitching: projected and actual':'Projected pitching'}</h2>${players(f,b,'pitching',true,actual)}<h2 id="simulatedGames">Simulated games</h2><div class="sample-buttons">${b.samples.map((x,i)=>`<button data-sample="${i}">${i===0?'Most typical score':'Simulated game '+(i+1)}<b class="num">${esc(f.away.abbr)} ${x.score.away} – ${esc(f.home.abbr)} ${x.score.home}</b></button>`).join('')}</div>${actual?`<h2>Player projection scores</h2>${gameScores(pk)}`:''}`:'<p class="placeholder">A full box score will appear with the next pregame forecast.</p>'}<details class="history-list"><summary>${D.view_scope==='historical_replay'?'Replay details':'Earlier forecasts'} (${versions(pk).length})</summary>${versionsHTML}</details>`;
 $('backSlate').onclick=()=>{location.hash='';tab('slate')};$('game').querySelectorAll('[data-sample]').forEach(el=>el.onclick=()=>openSample(Number(el.dataset.sample)));tab('game');location.hash='game-'+pk;}
function openSample(index){sample=index;const f=latest(current)[1],b=boxFor(current)[1],g=b.samples[index];const halves=new Map();for(const p of g.plays){const key=p.inning+'-'+p.half;if(!halves.has(key))halves.set(key,[]);halves.get(key).push(p);}
 $('sample').innerHTML=`<button id="backGame">Back to projected box</button><h1>${index===0?'Most typical score':'Simulated game '+(index+1)}</h1><p class="status-note">One of 10,000 simulated games. Not an actual result.</p><div class="board">${['away','home'].map(s=>`<div class="board-team"><span class="name">${teamName(f,s)}</span><span></span><b class="num">${g.score[s]}</b></div>`).join('')}</div><h2>Line score</h2>${lineScore(f,g.innings,g.batting,false)}<h2>Batting</h2>${players(f,g,'batting',false,null)}<h2>Pitching</h2>${players(f,g,'pitching',false,null)}<h2>Play by play</h2>${[...halves].map(([key,plays],i)=>`<details class="play-half" ${i===0?'open':''}><summary>${plays[0].half==='top'?'Top':'Bottom'} ${plays[0].inning}</summary>${plays.map(p=>`<div class="play"><p><strong>${esc(p.batter_name)}</strong></p><p>${esc(p.description.replace('reached on a walk or hit by pitch.',p.box_outcome==='walk'?'walked.':'was hit by a pitch.'))}</p><div class="play-result"><span>${p.outs_after} out${p.outs_after===1?'':'s'}</span><span class="num">${esc(f.away.abbr)} ${p.away_score} – ${esc(f.home.abbr)} ${p.home_score}</span></div></div>`).join('')}</details>`).join('')}`;$('backGame').onclick=()=>openGame(current);tab('sample');}
function gameScores(pk){const v=(D.player_scores?.versions||[]).filter(v=>String(v.game_pk)===String(pk)).at(-1);if(!v)return '<p>Player scoring is waiting for a final, checked box score.</p>';const groups={};for(const r of v.rows){const key=(r.kind==='batting'?'Batter ':'Pitcher ')+r.metric;(groups[key]??=[]).push(r.crps);}
 return `<table class="scoretable"><thead><tr><th>Player stat</th><th>Score</th><th>Players</th></tr></thead><tbody>${Object.entries(groups).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="num">${n3(v.reduce((a,b)=>a+b,0)/v.length)}</td><td class="num">${v.length}</td></tr>`).join('')}</tbody></table>`;}
function renderTrack(){const s=D.scores||{},ps=D.player_scores||{};let games=[...new Set(Object.values(D.forecasts).map(f=>String(f.game_pk)))];$('track').innerHTML=`<h1>Track record</h1><p class="status-note">Lower scores mean better forecasts. ${s.n_games||0} games scored.</p>${metrics()}<table class="scoretable"><thead><tr><th>Log loss</th><th>Model</th><th>Baseline</th></tr></thead><tbody><tr><td>Game winner</td><td class="num">${n3(s.model_corrected_log_loss)}</td><td class="num">${n3(s.team_log_loss)}</td></tr></tbody></table><h2>Player forecasts</h2>${ps.aggregates?.length?`<table class="scoretable"><thead><tr><th>Stat</th><th>Score</th><th>Player games</th></tr></thead><tbody>${ps.aggregates.map(x=>`<tr><td>${x.kind==='batting'?'Batter':'Pitcher'} ${x.metric}</td><td class="num">${n3(x.crps)}</td><td class="num">${x.n_player_games}</td></tr>`).join('')}</tbody></table><h3>Hit and home-run chances</h3><table class="scoretable"><thead><tr><th>At least one</th><th>Brier</th><th>Player games</th></tr></thead><tbody>${ps.aggregates.filter(x=>x.event_brier!==null).map(x=>`<tr><td>${x.metric==='H'?'Hit':'Home run'}</td><td class="num">${n3(x.event_brier)}</td><td class="num">${x.n_player_games}</td></tr>`).join('')}</tbody></table>`:'<p>Player scores begin when a game with saved player projections finishes.</p>'}<h2>Saved forecasts</h2>${games.map(pk=>{let [id,f]=latest(pk),a=D.actuals[pk];return `<article class="track-game"><h3>${teamName(f,'away')} at ${teamName(f,'home')}</h3><p>${esc(f.date)}. ${eastern(f.saved_at)}</p><p>Projected ${n1(f.projected_away_runs)} – ${n1(f.projected_home_runs)} ${a?`<span class="actual-chip">Actual ${a.away} – ${a.home}</span>`:'<span>Not final</span>'}</p><button data-track-game="${pk}">Open box score</button></article>`}).join('')}`;$('track').querySelectorAll('[data-track-game]').forEach(el=>el.onclick=()=>openGame(el.dataset.trackGame));}
function renderHow(){$('how').innerHTML=`<div class="notes"><h1>How to read this</h1><h2>One game, 10,000 times</h2><p>Each simulated game uses the locked plate-appearance model, then advances runners and changes pitchers. Batting and pitching projections average all 10,000 games. A pitcher's average includes zero innings in simulations where he does not appear. The numbers are the model's view, not a guarantee.</p><h2>Reading a box score</h2><p>PA means plate appearances; AB at bats; H hits; 2B doubles; HR home runs; R runs; RBI runs batted in; BB walks; K strikeouts; HBP hit by pitch. Hit chance and HR chance mean at least one in the full game. Projected innings are ordinary decimal innings; an actual or single simulated pitching line uses baseball notation, so 5.2 means five innings and two outs.</p><h2>Pitch counts and walks</h2><p>Pitches marked with * are estimates from the pitcher's earlier plate-appearance lengths, conditional on the selected outcome and batter hand, with a league fallback if no matching history exists. Walks and hit-by-pitches are separated from the pooled model category using the same prior-date empirical samples. These annotations use a separate random stream and do not change winners or pitcher removal. There are no pitch-by-pitch sequences yet.</p><h2>Projected innings and sample games</h2><p>An inning not played contributes zero to the projected average. Extra innings are shown individually. The most typical example uses the most frequent exact score pair among the 10,000 simulations; four more examples use fixed world positions. They are examples, not the five most likely games. Every batting run and every hit reconciles with the team score and opposing pitching lines.</p><h2>Actual results</h2><p>Amber marks actual statistics from the official MLB Stats API. Actual player rows are joined by player ID, never by name or batting-order guess. Late substitutes without a saved prediction remain visible but unscored. A projected pitcher who never appears receives zero realized innings. Final totals must reconcile before player scores are accepted.</p><h2>Proper scoring</h2><p>Player hit, home-run and strikeout counts use CRPS from their complete simulated distributions. Pitcher strikeouts and innings use the same score; innings are calculated from outs, then divided by three. Hit and home-run occurrence also receive Brier scores. Finite-simulation corrections exclude self-pairs. Lower is better, but count scores across different statistics have different scales. Players in the same game are dependent: more player rows do not create independent game-level evidence.</p><h2>Timing</h2><p>All displayed times are Eastern, including daylight-saving changes. Player forecasts have their own public timestamp. We only score a box projection published before the game's observed first pitch, even if a simpler win forecast was saved earlier. Forecast versions and source revisions remain unchanged. Actual box scores are read only after forecasting and never become inputs for the same game.</p><h2>Known limits</h2><p>Postseason games still use regular-season bullpen logic and no automatic runner in extra innings. No pinch hitters, steals, wild pitches, or passed balls are simulated yet. Speed, defense, and reliever rest retain the legacy assumptions. The seed history's historical publication times remain unverified; newly captured daily updates are timestamped and encrypted. Current 2025 calibration prevents this live model from being used for a clean 2025 test.</p></div>`;}
$('slateTab').onclick=()=>{location.hash='';tab('slate')};$('trackTab').onclick=()=>{location.hash='track';renderTrack();tab('track')};$('howTab').onclick=()=>{location.hash='how';tab('how')};renderSlate();renderTrack();renderHow();if(location.hash.startsWith('#game-'))openGame(location.hash.slice(6));else if(location.hash==='#track')tab('track');else if(location.hash==='#how')tab('how');
'''


def render_page(ledger,scores,destination,setup_message=None,*,replay=False):
    if replay:
        if ledger.get('publications') or ledger.get('box_publications') or scores.get('n_games'):
            raise ValueError('Historical UI replay cannot carry live publication/scoring evidence')
    else:
        for f in ledger['forecasts'].values():check_public(f)
    public={k:ledger.get(k,{}) for k in ('date','forecasts','publications','actuals','status','box_scores','box_publications','actual_boxes','player_scores')}
    public['scores']=scores
    public['view_scope']='historical_replay' if replay else 'live'
    data=canonical(public).decode().replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Baseball Research Lab</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Barlow+Condensed:wght@400;500;600;700&display=swap" rel="stylesheet"><style>'''+CSS+'''</style></head><body><div class="topbar"><div class="topbar-inner"><a class="brand" href="#" onclick="tab('slate');return false">Baseball Research Lab</a></div></div><main><nav class="nav" aria-label="Pages"><button id="slateTab" aria-selected="true">Game cards</button><button id="trackTab" aria-selected="false">Track record</button><button id="howTab" aria-selected="false">How to read this</button></nav><section id="slate"></section><section id="game" hidden></section><section id="sample" hidden></section><section id="track" hidden></section><section id="how" hidden></section></main><script>window.BRL='''+data+';</script><script>'+JS+'</script></body></html>'
    d=Path(destination);d.mkdir(parents=True,exist_ok=True)
    (d/'index.html').write_text(doc,encoding='utf-8');(d/'predictions.json').write_bytes(canonical(public));(d/'.nojekyll').write_text('')
    return d/'index.html'
